DO $$ DECLARE t text; BEGIN IF NOT EXISTS (SELECT 1 FROM pg_publication WHERE pubname='supabase_realtime') THEN CREATE PUBLICATION supabase_realtime; END IF; FOREACH t IN ARRAY ARRAY['trips','trip_stops','gate_passes','gate_entries','trip_loading','trip_alerts','cash_handovers','trip_collections','trip_returns','orders'] LOOP IF NOT EXISTS (SELECT 1 FROM pg_publication_tables WHERE pubname='supabase_realtime' AND schemaname='public' AND tablename=t) THEN EXECUTE format('ALTER PUBLICATION supabase_realtime ADD TABLE public.%I',t); END IF; END LOOP; END $$;